    combined20_1(t_039) <= delay20(t_039) + delay23(t_039);
  END GENERATE combined20_1_gen;


  gain20_mul_temp <= to_signed(16#60B7#, 16) * combined20_1(0);
  gain20_1(0) <= resize(gain20_mul_temp, 33);
  gain20_mul_temp_1 <= to_signed(16#60B7#, 16) * combined20_1(1);
  gain20_1(1) <= resize(gain20_mul_temp_1, 33);


  add_39_gen: FOR t_040 IN 0 TO 1 GENERATE
    add_add_cast_20(t_040) <= resize(gain20_1(t_040), 38);
    add_39(t_040) <= add_37(t_040) + add_add_cast_20(t_040);
  END GENERATE add_39_gen;



  combined21_1_gen: FOR t_041 IN 0 TO 1 GENERATE
    combined21_1(t_041) <= delay21(t_041) + delay22(t_041);
  END GENERATE combined21_1_gen;


  gain21_mul_temp <= to_signed(16#75B8#, 16) * combined21_1(0);
  gain21_1(0) <= resize(gain21_mul_temp, 33);
  gain21_mul_temp_1 <= to_signed(16#75B8#, 16) * combined21_1(1);
  gain21_1(1) <= resize(gain21_mul_temp_1, 33);


  Discrete_FIR_Filter_out_tmp_gen: FOR t_042 IN 0 TO 1 GENERATE
    add_add_cast_21(t_042) <= resize(gain21_1(t_042), 38);
    Discrete_FIR_Filter_out_tmp(t_042) <= add_39(t_042) + add_add_cast_21(t_042);
  END GENERATE Discrete_FIR_Filter_out_tmp_gen;


  outputgen: FOR k IN 0 TO 1 GENERATE
    Discrete_FIR_Filter_out(k) <= std_logic_vector(Discrete_FIR_Filter_out_tmp(k));
  END GENERATE;

END rtl;

